CREATE TABLE IF NOT EXISTS products (
    id TEXT PRIMARY KEY,
    name TEXT,
    barcode TEXT,
    barcodeType TEXT,
    unit TEXT,
    brand TEXT,
    category TEXT,
    quantity REAL DEFAULT 0,
    buy_price REAL DEFAULT 0,
    sell_price REAL DEFAULT 0,
    wholesale_price REAL DEFAULT 0,
    shop_sell_price REAL DEFAULT 0,
    shop_wholesale_price REAL DEFAULT 0,
    alertQuantity REAL,
    description TEXT,
    packetPerBox REAL,
    pcsPerBox REAL,
    pcsPerPacket REAL,
    imageUrl TEXT,
    lots TEXT,
    created_at DATETIME,
    updated_at DATETIME
);
